	operator bool() const {
		return is_available();
	}

	void initialize(GDExtensionInterfaceGetProcAddress p_get_proc_address);

private:
	bool is_available() const {
		return isInitialized;
	}

	template <typename T>
	T resolve(const char *p_name) const {
		return get_proc_address != nullptr
				? reinterpret_cast<T>(get_proc_address(p_name))
				: nullptr;
	}

	bool isInitialized = false;
